export default function WorkList({ works, profile, initialFilter }) {
  const [viewMode, setViewMode] = useState("month"); // month | week | day
  const [filterMonth, setFilterMonth] = useState(initialFilter?.month || fmt.today().slice(0,7));
  const [filterWeek, setFilterWeek] = useState(()=>getWeekRange(new Date()).start);
  const [filterDay, setFilterDay] = useState(fmt.today());
  const [filterPay, setFilterPay] = useState(initialFilter?.payment || "");
  const [filterWorker, setFilterWorker] = useState("");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState(null);
  const [editTarget, setEditTarget] = useState(null);
  const [showDetail, setShowDetail] = useState(false);
  const [opinionCountByWork, setOpinionCountByWork] = useState({});
  const [quickLightbox, setQuickLightbox] = useState(null); // {images:[...], index:n}
  const [confirmingPaymentId, setConfirmingPaymentId] = useState(null); // 입금확인 처리 중인 작업 id
  const [autoOpenedFor, setAutoOpenedFor] = useState(null); // 일정 화면에서 특정 작업으로 바로 이동한 workId 추적(중복 자동열기 방지)

  // 일정 화면의 "작업일지 보기"에서 특정 workId로 넘어온 경우, 목록 필터와 무관하게 상세 모달을 바로 연다.
  // works가 아직 로딩 중이어도(초기 빈 배열) works가 갱신될 때마다 다시 시도하되, 한 번 연 뒤에는 다시 열지 않는다.
  useEffect(() => {
    if (initialFilter?.workId && initialFilter.workId !== autoOpenedFor) {
      const w = works.find(w => w.id === initialFilter.workId);
      if (w) { setSelected(w); setAutoOpenedFor(initialFilter.workId); }
    }
  }, [initialFilter?.workId, works, autoOpenedFor]);

  // 외상 건을 "입금 확인" 처리 - 결제방식을 현금(cash)으로 전환한다.
  // (요구사항: 계좌이체 등 다른 수단으로 실제 받았더라도, 입금확인 시에는 무조건 현금으로 전환)
  const handleConfirmPayment = async (work) => {
    if (!window.confirm(`"${work.clientCompany}" 건 ${fmt.money(work.netAmount||work.amount)}을(를) 입금 확인 처리할까요?\n결제방식이 "외상"에서 "현금"으로 변경됩니다.`)) return;
    setConfirmingPaymentId(work.id);
    try {
      await updateDoc(doc(db, "works", work.id), { payment: "cash", updatedAt: new Date().toISOString() });
    } catch (e) {
      alert("입금확인 처리 중 오류: " + e.message);
    }
    setConfirmingPaymentId(null);
  };

  // 소견서 작성 여부 배지 표시용 — workId별 개수만 집계 (쿼리 1회)
  useEffect(() => {
    const q = query(collection(db, "opinions"));
    return onSnapshot(q, snap => {
      const counts = {};
      snap.docs.forEach(d => {
        const wid = d.data().workId;
        if (wid) counts[wid] = (counts[wid] || 0) + 1;
      });
      setOpinionCountByWork(counts);
    });
  }, []);

  // 날짜 필터링
  const dateFiltered = works.filter(w=>{
    if (viewMode==="month") return w.date?.startsWith(filterMonth);
    if (viewMode==="week") {
      const week = getWeekRange(new Date(filterWeek+"T00:00:00"));
      return w.date>=week.start && w.date<=week.end;
    }
    if (viewMode==="day") return w.date===filterDay;
    return true;
  });

  // 검색·결제·작업자 필터
  const filtered = dateFiltered.filter(w=>{
    const s = search.toLowerCase();
    const matchS = !s||[w.clientCompany,w.location,w.content,w.workerName,w.workerCompany,(w.equipment||[]).join(",")].some(v=>v?.toLowerCase().includes(s));
    const matchP = !filterPay||w.payment===filterPay;
    const matchW = !filterWorker||w.workerName===filterWorker;
    return matchS&&matchP&&matchW;
  });

  // 집계
  const total  = filtered.reduce((s,w)=>s+(Number(w.netAmount||w.amount)||0),0);
  const fee    = filtered.reduce((s,w)=>s+(Number(w.feeAmount)||0),0);
  const cash   = filtered.filter(w=>w.payment==="cash").reduce((s,w)=>s+(Number(w.netAmount||w.amount)||0),0);
  const card   = filtered.filter(w=>w.payment==="card").reduce((s,w)=>s+(Number(w.netAmount||w.amount)||0),0);
  const credit = filtered.filter(w=>w.payment==="credit").reduce((s,w)=>s+(Number(w.netAmount||w.amount)||0),0);

